// Generated from content\spelling.seed.json via scripts/generate-spelling-content.mjs
// Keep the Worker seed compressed so the deployed script stays under Cloudflare's Free plan size limit.

const SEEDED_SPELLING_CONTENT_BUNDLE_GZIP_BASE64 = "";
const SEEDED_SPELLING_PUBLISHED_SNAPSHOT_GZIP_BASE64 = "";

export const SEEDED_SPELLING_CONTENT_SUMMARY = {
  "wordListCount": 19,
  "wordCount": 1480,
  "sentenceCount": 3447,
  "releaseCount": 8,
  "errorCount": 0,
  "warningCount": 6,
  "publishedReleaseId": "spelling-r8",
  "publishedVersion": 8,
  "publishedAt": 1780660800000,
  "runtimeWordCount": 1480,
  "runtimeSentenceCount": 3447,
  "coverageTierCounts": {
    "statutoryCore": 213,
    "secureExtension": 1215,
    "enrichmentExtra": 52,
    "total": 1480
  },
  "statutoryCoreCount": 213,
  "secureExtensionCount": 1215,
  "enrichmentExtraCount": 52,
  "ok": true
};

let contentBundlePromise = null;
let publishedSnapshotPromise = null;

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

async function inflateJsonFromBase64(value) {
  if (typeof DecompressionStream !== 'function') {
    throw new Error('DecompressionStream is required to read the compressed spelling seed.');
  }
  const stream = new Blob([decodeBase64(value)]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}

export function readSeededSpellingContentBundle() {
  if (!contentBundlePromise) {
    contentBundlePromise = inflateJsonFromBase64(SEEDED_SPELLING_CONTENT_BUNDLE_GZIP_BASE64);
  }
  return contentBundlePromise;
}

export function readSeededSpellingPublishedSnapshot() {
  if (!publishedSnapshotPromise) {
    publishedSnapshotPromise = inflateJsonFromBase64(SEEDED_SPELLING_PUBLISHED_SNAPSHOT_GZIP_BASE64);
  }
  return publishedSnapshotPromise;
}
